class HashTable:
    def __init__(self, size):
        self.size = size
        self.table = [None] * size

    def _probe(self, key):
        start = key % self.size
        for step in range(self.size):
            cell = self.table[(start + step) % self.size]
            if cell is None or cell == key:
                return step + 1
        return self.size

    def insert(self, key):
        start = key % self.size
        for step in range(self.size):
            slot = (start + step) % self.size
            if self.table[slot] is None:
                self.table[slot] = key
                return True
            if self.table[slot] == key:
                return False
        return False

    def search(self, key):
        start = key % self.size
        for step in range(self.size):
            cell = self.table[(start + step) % self.size]
            if cell is None:
                return False
            if cell == key:
                return True
        return False

    def probes(self, key):
        return self._probe(key)

    def asl(self):
        keys = [cell for cell in self.table if cell is not None]
        if not keys:
            return 0.0
        return sum(self._probe(k) for k in keys) / len(keys)

table = HashTable(7)
for key in [3, 10, 17, 24]:
    table.insert(key)
print([table.probes(key) for key in [3, 10, 17, 24]], table.asl())
print(table.search(24), table.search(4))
print(table.insert(3))
